window.kbPageData["views/entry/k-2ea1431b5ab948ff"] = {"key":"entry/k-2ea1431b5ab948ff","state":{"route":"entry/k-2ea1431b5ab948ff"},"node":{"id":"k-2ea1431b5ab948ff","mode":"k","title":"主要矛盾","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":["唯物辩证法 · 主要矛盾对事物发展起决定作用"],"qs":["政治理论必刷100题#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["原理与机制"],"出处性质":["专项题解析","理论手册"],"学科":["哲学"],"资料类别":["政治理论专项","非时政"]},"seeAlso":["k-15e08a19cc250aed","k-bbfcc1599e79a235"],"supplement":[{"doc":"3ccc56f4000d1642c2d1","file":"政治理论必学手册.pdf","first":4,"last":4,"relation":"辨析","evidenceId":"50f59d7e0d9ae9d6b073","cardId":"c394cdef1420fc60","questionId":null,"basis":"理论手册","quote":"（粉笔敲黑板：通俗来讲，普遍性强调的是“都有”，特殊性强调的是“不一样”）（4）矛盾的不平衡性①主要矛盾和次要矛盾主要矛盾是指在诸多矛盾中处于支配地位、对事物发展起决定作用的矛盾；","text":"多种矛盾并存时，找出对事物发展起决定作用的那一个。","reference":null}],"directorySummary":"主要矛盾是复杂事物在一定发展阶段的多种矛盾中居于支配地位、对事物发展起决定作用的矛盾。处理复杂问题时，应优先抓住主要矛盾。","review":{"definition":"主要矛盾是复杂事物在一定发展阶段的多种矛盾中居于支配地位、对事物发展起决定作用的矛盾。处理复杂问题时，应优先抓住主要矛盾。","explanation":"C项用树根仍在则树木可再生、水源仍在则水可复流，说明只处理眼前表现，问题还会反复。题中以树根和水源比喻解决问题的关键，用来说明办事要抓住主要矛盾。","references":[{"source":"web-0862221d6fd6fced","location":"卷七《晋语一》，“驪姬既嬖”段史苏语","quote":"伐木不自其本，必復生"}],"evidence":"伐木不自其本，必复生；塞水不自其源，必复流","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"政治理论必刷100题#1":{"paper":"政治理论必刷100题","n":1,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",1],"asrc":["国省考政治理论必刷100题.pdf",31],"card":"43ce773e203183ac9c97b221","links":[{"id":"k-2ea1431b5ab948ff","role":"直接考查","why":"树根和水源分别决定树木能否再生、水能否复流，说明解决问题要抓住主要矛盾。"}]}},"terms":{"k-15e08a19cc250aed":{"id":"k-15e08a19cc250aed","mode":"k","type":"原理与机制","title":"矛盾的主要方面","qs":[],"count":0},"k-bbfcc1599e79a235":{"id":"k-bbfcc1599e79a235","mode":"k","type":"原理与机制","title":"矛盾的普遍性、特殊性和客观性","qs":[],"count":3}},"references":{"web-0862221d6fd6fced":{"name":"《国语·晋语一》","url":"https://upload.wikimedia.org/wikipedia/commons/f/f0/NLC416-06jh008837-2150_%E5%9C%8B%E8%AA%9E.pdf"}},"topics":[],"units":{"k-2ea1431b5ab948ff":[["政治理论必刷100题#1"]]}};
